List<String> names = Arrays.asList("Java", "Kotlin", "Scala");

// Using a lambda expression with the Stream API
names.stream()
     .filter(name -> name.startsWith("J"))
     .map(String::toUpperCase)
     .forEach(System.out::println);

// Lambda as a variable
